//! A generated C header is valid C and valid C++: every canonical example is
//! generated by the C backend and syntax-checked with `gcc -std=c99` (warnings
//! as errors) and with `g++ -std=c++17`, which refuses the implicit
//! `void*` to typed-pointer conversion C allows. Each compiler is skipped,
//! with a message, when it is not installed.

#![allow(clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::Path;
use std::process::Command;

use hddsgen::codegen::c::CGenerator;
use hddsgen::codegen::CodeGenerator;
use hddsgen::Parser;

fn available(tool: &str) -> bool {
    Command::new(tool).arg("--version").output().is_ok()
}

fn check(tool: &str, args: &[&str], dir: &Path, wrapper: &Path, failures: &mut Vec<String>) {
    let out = Command::new(tool)
        .args(args)
        .arg("-I")
        .arg(dir)
        .arg(wrapper)
        .output()
        .expect("run compiler");
    if !out.status.success() {
        let text = String::from_utf8_lossy(&out.stderr);
        let first: Vec<&str> = text
            .lines()
            .filter(|l| l.contains("error"))
            .take(3)
            .collect();
        failures.push(format!(
            "{tool} {}: {}",
            wrapper.display(),
            first.join(" | ")
        ));
    }
}

#[test]
fn canonical_c_headers_compile_as_c_and_cpp() {
    let have_gcc = available("gcc");
    let have_gxx = available("g++");
    if !have_gcc && !have_gxx {
        eprintln!("neither gcc nor g++ found; skipping the C header compile test");
        return;
    }
    let canonical = Path::new(env!("CARGO_MANIFEST_DIR")).join("examples/canonical");
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join("c_header_cpp_compat");
    fs::create_dir_all(&dir).expect("temp dir");

    let mut idls: Vec<_> = fs::read_dir(&canonical)
        .expect("examples/canonical")
        .filter_map(Result::ok)
        .map(|e| e.path())
        .filter(|p| p.extension().is_some_and(|x| x == "idl"))
        .collect();
    idls.sort();
    assert_eq!(idls.len(), 17, "the canonical corpus has 17 IDL files");

    let mut failures = Vec::new();
    for idl in &idls {
        let name = idl.file_stem().and_then(|s| s.to_str()).expect("stem");
        let text = fs::read_to_string(idl).expect("read idl");
        let mut parser = Parser::try_new(&text).expect("lexer");
        let ast = parser.parse().expect("parse");
        let header = CGenerator::new().generate(&ast).expect("c codegen");
        fs::write(dir.join(format!("{name}.h")), header).expect("write header");
        let c_wrap = dir.join(format!("{name}_wrap.c"));
        let cpp_wrap = dir.join(format!("{name}_wrap.cpp"));
        fs::write(&c_wrap, format!("#include \"{name}.h\"\n")).expect("wrapper");
        fs::write(&cpp_wrap, format!("#include \"{name}.h\"\n")).expect("wrapper");
        if have_gcc {
            check(
                "gcc",
                &["-std=c99", "-Wall", "-Wextra", "-Werror", "-fsyntax-only"],
                &dir,
                &c_wrap,
                &mut failures,
            );
        }
        if have_gxx {
            check(
                "g++",
                &["-std=c++17", "-fsyntax-only"],
                &dir,
                &cpp_wrap,
                &mut failures,
            );
        }
    }
    assert!(
        failures.is_empty(),
        "generated C headers that do not compile:\n{}",
        failures.join("\n")
    );
}

/// An element type that cannot be named in a cast (a nested sequence or map
/// is an anonymous structure) still compiles as C++.
#[test]
fn nested_anonymous_elements_compile_as_cpp() {
    if !available("g++") {
        eprintln!("g++ not found; skipping");
        return;
    }
    let dir = Path::new(env!("CARGO_TARGET_TMPDIR")).join("c_header_cpp_nested");
    fs::create_dir_all(&dir).expect("temp dir");
    let idl = "struct A { long x; };
struct N {
    sequence<sequence<long>> ss;
    sequence<A> sa;
    map<string, sequence<long>> m;
    sequence<long> arr[2];
    sequence<sequence<A, 2>> q;
    sequence<string<5>> bs;
};";
    let mut parser = Parser::try_new(idl).expect("lexer");
    let ast = parser.parse().expect("parse");
    let header = CGenerator::new().generate(&ast).expect("c codegen");
    fs::write(dir.join("n.h"), header).expect("write");
    let wrap = dir.join("n_wrap.cpp");
    fs::write(&wrap, "#include \"n.h\"\n").expect("wrap");
    let mut failures = Vec::new();
    check(
        "g++",
        &["-std=c++17", "-fsyntax-only"],
        &dir,
        &wrap,
        &mut failures,
    );
    if available("gcc") {
        let cwrap = dir.join("n_wrap.c");
        fs::write(&cwrap, "#include \"n.h\"\n").expect("wrap");
        check(
            "gcc",
            &["-std=c99", "-Wall", "-Wextra", "-Werror", "-fsyntax-only"],
            &dir,
            &cwrap,
            &mut failures,
        );
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}
